Here's a plugin to try~
Spoiler:
plugin code
JavaScript:
/*:
 * @target MZ
 * @plugindesc Animations below battlers.
 * @author Caethyril
 * @url https://forums.rpgmakerweb.com/threads/172532/
 * @help Give "below" animations a name starting with an underscore.
 * E.g. "_Aura".
 *
 * Free to use and/or modify for any project, no credit required.
 */
;void (() => {
'use strict';
  /** Regular expression matching below-battler animation names. */
  const RX = /^_/;  // "starts with _"

  /**
   * @param {$dataAnimation} anim Database animation record to check.
   * @returns {boolean} `true` iff given animation should show below battlers.
   */
  const isBelowAnim = function(anim) {
    const n = anim?.name;
    return n ? RX.test(n) : false;
  };

  /** Identifier for new "below" effects container property on `Spriteset_Battle`. */
  const C2 = "_effectsContainerBelow";

  /** Non-conflicting identifier for get-and-erase method for `store`. */
  const SYM = Symbol();

  /** Private storage for latest value intercepted by {@linkcode fakeContainer}. */
  let store = null;

  /** Interceptor for add child calls. */
  const fakeContainer = Object.freeze({
    [SYM]: function() { const o = store; store = null; return o; },
    addChild: function(o = null) { store = o; }
  });

  // Patch - create "below" effects container.
  void (alias => {
    Spriteset_Battle.prototype.createBattleField = function() {
      const c = this[C2] = new Sprite();
      this._baseSprite.addChild(c);
      alias.apply(this, arguments);
      c.updateTransform = function() {
        Sprite.prototype.updateTransform.apply(this, arguments);
        this.transform.updateTransform(this.parent.parent._battleField.transform);
      };
    };
  })(Spriteset_Battle.prototype.createBattleField);

  // Patch - redirect below-type anim creation calls.
  void (alias => {
    Spriteset_Battle.prototype.createAnimationSprite = function(targets, animation) {
      const c = isBelowAnim(animation) ? this._effectsContainer : null;
      if (c)
        this._effectsContainer = fakeContainer;
      alias.apply(this, arguments);
      if (c) {
        this._effectsContainer = c;
        this[C2].addChild(fakeContainer[SYM]())
      }
    };
  })(Spriteset_Battle.prototype.createAnimationSprite);

  // Patch - also remove from "below" effects container.
  void (alias => {
    Spriteset_Battle.prototype.removeAnimation = function(sprite) {
      if (isBelowAnim(sprite?._animation))
        this[C2].removeChild(sprite);
      alias.apply(this, arguments);
    };
  })(Spriteset_Battle.prototype.removeAnimation);

})();
As mentioned in the help, it uses the animation's database name to decide which layer each animation should play on. You can edit this line to customise that:
JavaScript:
const RX = /^_/;  // "starts with _"

